"""In-place foreach cosh: ``aten::_foreach_cosh_(Tensor(a!)[] self) -> ()``.

Every list element is transformed in place (same storage, same strides) and the
call returns ``None``.  The element-wise math is ``cosh(x) = (exp(x)+exp(-x))/2``
rounded back to the element dtype.  The arithmetic runs in the storage dtype for
the 2-byte types, where the wider vector instructions (128 lanes per op) matter
more than fp32 opmath precision, and in fp32 for float32 elements.

Only Triton kernels produce output values; the host side is limited to
metadata reads, stride planning, grid arithmetic and the launches.

Launch decomposition:
* homogeneous flat Tensor list -> ONE fused launch (``_cosh_multi``) whose grid
  covers ``T * chunks`` programs; each program picks its tensor through a
  constexpr-guarded chain of pointer arguments, so no metadata has to be copied
  to the device and the per-tensor launch cost disappears.
* otherwise                    -> one direct launch per tensor.
"""

import torch
import triton
import triton.language as tl

_BLOCK = 8192
_BLOCK_2B = 16384
_MAX_RANK = 8
_MAX_T = 16


def _block_for(dtype):
    """Tile length: 2-byte elements can hold a twice-longer tile in the UB."""
    if dtype is torch.float16 or dtype is torch.bfloat16:
        return _BLOCK_2B
    return _BLOCK


def _acc_dtype(dtype):
    """Arithmetic dtype for one element dtype (a compile-time constant)."""
    if dtype is torch.float16:
        return tl.float16
    if dtype is torch.bfloat16:
        return tl.bfloat16
    return tl.float32


@triton.jit
def _cosh_f(x, ACC_DT: tl.constexpr):
    xf = x.to(ACC_DT)
    return 0.5 * (tl.exp(xf) + tl.exp(-xf))


@triton.jit
def _cosh_tile(p, n, offs, ACC_DT: tl.constexpr):
    mask = offs < n
    x = tl.load(p + offs, mask=mask, other=0.0)
    y = _cosh_f(x, ACC_DT)
    tl.store(p + offs, y.to(p.dtype.element_ty), mask=mask)


@triton.jit
def _cosh_flat(x_ptr, n, ACC_DT: tl.constexpr, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    _cosh_tile(x_ptr, n, pid * BLOCK + tl.arange(0, BLOCK), ACC_DT)


@triton.jit
def _cosh_strided(
    x_ptr,
    n,
    d0,
    s0,
    d1,
    s1,
    d2,
    s2,
    d3,
    s3,
    d4,
    s4,
    d5,
    s5,
    d6,
    s6,
    d7,
    s7,
    ACC_DT: tl.constexpr,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    i = offs
    addr = (i % d0) * s0
    if RANK > 1:
        i = i // d0
        addr += (i % d1) * s1
    if RANK > 2:
        i = i // d1
        addr += (i % d2) * s2
    if RANK > 3:
        i = i // d2
        addr += (i % d3) * s3
    if RANK > 4:
        i = i // d3
        addr += (i % d4) * s4
    if RANK > 5:
        i = i // d4
        addr += (i % d5) * s5
    if RANK > 6:
        i = i // d5
        addr += (i % d6) * s6
    if RANK > 7:
        i = i // d6
        addr += (i % d7) * s7
    x = tl.load(x_ptr + addr, mask=mask, other=0.0)
    y = _cosh_f(x, ACC_DT)
    tl.store(x_ptr + addr, y.to(x_ptr.dtype.element_ty), mask=mask)


