def _is_flat_addressable(t):
    """True when [data_ptr, data_ptr + numel) covers exactly this tensor."""
    if t.is_contiguous():
        return True
    if t.numel() <= 1:
        return True
    expected = 1
    for stride, size in sorted(
        (s, sz) for s, sz in zip(t.stride(), t.shape) if sz != 1
    ):
        if stride != expected:
            return False
        expected *= size
    return True


def _stride_plan(t):
    """Collapse and sort strides so the fastest-varying dim comes first."""
    dims = sorted(
        ((sz, st) for sz, st in zip(t.shape, t.stride()) if sz != 1),
        key=lambda d: d[1],
    )
    merged = []
    for sz, st in dims:
        if merged and merged[-1][1] * merged[-1][0] == st:
            merged[-1] = (merged[-1][0] * sz, merged[-1][1])
        else:
            merged.append((sz, st))
    return merged


def foreach_cosh_(self):
    if not isinstance(self, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    tensors = list(self)
    if not tensors:
        raise RuntimeError("Tensor list must have at least one tensor.")

    plans = []
    same_dtype = True
    first_dtype = None
    all_flat = True
    for t in tensors:
        if not torch.is_tensor(t):
            raise TypeError("argument 'self' must be tuple of Tensors")
        dtype = t.dtype
        if dtype.is_complex:
            raise NotImplementedError("complex cosh is not supported yet")
        if not dtype.is_floating_point:
            raise RuntimeError(
                "result type Float can't be cast to the desired output type "
                + str(dtype).replace("torch.", "").capitalize()
            )
        if first_dtype is None:
            first_dtype = dtype
        elif dtype is not first_dtype:
            same_dtype = False
        n = t.numel()
        if n == 0:
            continue
        if _is_flat_addressable(t):
            plans.append((t, n, None))
        else:
            all_flat = False
            dims = _stride_plan(t)
            if len(dims) > _MAX_RANK:
                raise NotImplementedError("rank too large for strided kernel")
            plans.append((t, n, dims))

    np_plans = len(plans)
    if np_plans == 0:
        return None

    acc_dt = _acc_dtype(first_dtype)
    blk = _block_for(first_dtype)

    if np_plans > 1 and all_flat and same_dtype and np_plans <= _MAX_T:
        nmax = 0
        nmin = plans[0][1]
        for _, n, _ in plans:
            if n > nmax:
                nmax = n
            if n < nmin:
                nmin = n
        chunks = (nmax + blk - 1) // blk
        ptrs = [p[0] for p in plans]
        nums = [p[1] for p in plans]
        # A tensor repeated in the list must be transformed once per
        # occurrence, in order.  The fused kernel would write the same
        # addresses from different programs, so such a list keeps the
        # sequential per-tensor path.
        if len({p.data_ptr() for p in ptrs}) == np_plans:
            last = ptrs[-1]
            uniform = nmin == nmax
            if uniform:
                while len(ptrs) < _MAX_T:
                    ptrs.append(last)
                _cosh_multi_u[(np_plans * chunks,)](
                    *ptrs,
                    nmax,
                    chunks,
                    acc_dt,
                    np_plans,
                    blk,
                )
                return None
            while len(ptrs) < _MAX_T:
                ptrs.append(last)
                nums.append(0)
            _cosh_multi[(np_plans * chunks,)](
                *ptrs,
                *nums,
                chunks,
                acc_dt,
                np_plans,
                blk,
            )
            return None

    for t, n, dims in plans:
        grid = ((n + blk - 1) // blk,)
        if dims is None:
            _cosh_flat[grid](t, n, acc_dt, blk)
        else:
            args = []
            for k in range(_MAX_RANK):
                if k < len(dims):
                    args.append(dims[k][0])
                    args.append(dims[k][1])
                else:
                    args.append(1)
                    args.append(0)
            _cosh_strided[grid](t, n, *args, acc_dt, len(dims), _BLOCK)
    return None
